PRAGMA foreign_keys = ON;
CREATE TABLE user (id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, emailVerified INTEGER NOT NULL DEFAULT 0, image TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE TABLE session (id TEXT PRIMARY KEY, expiresAt INTEGER NOT NULL, token TEXT NOT NULL UNIQUE, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL, ipAddress TEXT, userAgent TEXT, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE);
CREATE INDEX session_user ON session(userId);
CREATE TABLE account (id TEXT PRIMARY KEY, accountId TEXT NOT NULL, providerId TEXT NOT NULL, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, accessToken TEXT, refreshToken TEXT, idToken TEXT, accessTokenExpiresAt INTEGER, refreshTokenExpiresAt INTEGER, scope TEXT, password TEXT, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX account_user ON account(userId);
CREATE TABLE verification (id TEXT PRIMARY KEY, identifier TEXT NOT NULL, value TEXT NOT NULL, expiresAt INTEGER NOT NULL, createdAt INTEGER NOT NULL, updatedAt INTEGER NOT NULL);
CREATE INDEX verification_identifier ON verification(identifier);
CREATE TABLE rateLimit (id TEXT PRIMARY KEY, key TEXT NOT NULL UNIQUE, count INTEGER NOT NULL, lastRequest INTEGER NOT NULL);
CREATE TABLE crews (id TEXT PRIMARY KEY, name TEXT NOT NULL, ownerId TEXT NOT NULL REFERENCES user(id), timezone TEXT NOT NULL, inviteCode TEXT NOT NULL UNIQUE, inviteCreatedAt INTEGER NOT NULL, createdAt INTEGER NOT NULL);
CREATE TABLE members (crewId TEXT NOT NULL REFERENCES crews(id) ON DELETE CASCADE, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, joinedAt INTEGER NOT NULL, PRIMARY KEY(crewId,userId));
CREATE INDEX member_user ON members(userId);
CREATE TABLE challenges (id TEXT PRIMARY KEY, crewId TEXT NOT NULL REFERENCES crews(id) ON DELETE CASCADE, name TEXT NOT NULL, description TEXT NOT NULL, days INTEGER NOT NULL CHECK(days BETWEEN 1 AND 90), startDay TEXT NOT NULL, endDay TEXT NOT NULL, creatorId TEXT NOT NULL REFERENCES user(id), createdAt INTEGER NOT NULL);
CREATE INDEX challenge_crew ON challenges(crewId);
CREATE TABLE participants (challengeId TEXT NOT NULL REFERENCES challenges(id) ON DELETE CASCADE, userId TEXT NOT NULL REFERENCES user(id) ON DELETE CASCADE, joinedDay TEXT NOT NULL, PRIMARY KEY(challengeId,userId));
CREATE TABLE checkins (id TEXT PRIMARY KEY, challengeId TEXT NOT NULL, userId TEXT NOT NULL, day TEXT NOT NULL, note TEXT NOT NULL, photo BLOB, photoType TEXT, createdAt INTEGER NOT NULL, FOREIGN KEY(challengeId,userId) REFERENCES participants(challengeId,userId) ON DELETE CASCADE, UNIQUE(challengeId,userId,day));
CREATE INDEX checkin_challenge ON checkins(challengeId,createdAt DESC);
CREATE TABLE appRateLimits (key TEXT PRIMARY KEY, count INTEGER NOT NULL, resetAt INTEGER NOT NULL);
